SELECT  FROM APIGRAB_SYSTEM_USER

    AND username LIKE CONCAT('%', #{username}, '%')
    AND role = #{role}
    AND status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.EnableStatusTypeHandler}

ORDER BY id DESC

